AOS.init(),
        $(".fancybox-thumb").fancybox({
    prevEffect: "none",
    nextEffect: "none",
    helpers: {
        title: {
            type: "outside"
        },
        thumbs: {
            width: 50,
            height: 50
        }
    }
});
$(".gallery_mob").slick({
    dots: true,
    infinite: true,
    speed: 300,
    slidesToShow: 1,
    autoplay: true,
    autoplaySpeed: 3000
});


$(document).ready(function () {
    var windowH = $(window).height();
    $(".top_slider").height(windowH);
});


$("a.contactFormBtn").on("click", function () {
    var ProjectType = $(this).attr("rel");
    var ProjectTypeInput = document.querySelectorAll('input[name$="project"]');
    $(ProjectTypeInput).val(ProjectType);
});


